style.css:
@-moz-document domain("roblox.com") {
/* Для главной страницы */
    body, #application-container, .main-content, .container-main {
        background-image: url(https://imgur.com/a/5oE6KSI) !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
    }

    /* Для страницы входа */
    .login-background {
        background-image: url(https://imgur.com/a/5oE6KSI) !important;
        background-size: cover !important;
    }

    /* Убирает белые фоны */
    .section-content, .games-page-container, .avatar-background {
        background: transparent !important;
    }
}
